import { test, expect } from '@playwright/test';

test.describe('Out of Stock Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display out-of-stock message when adding unavailable item to cart', async ({ page }) => {
    await page.getByText('Unavailable Item').click(); // Replace with the actual item name
    await page.getByRole('button', { name: 'Add to Cart' }).click();

    const outOfStockMessage = await page.getByText('This item is currently out of stock.');
    await expect(outOfStockMessage).toBeVisible();
  });

  test('should not allow adding out-of-stock item to cart', async ({ page }) => {
    await page.getByText('Unavailable Item').click(); // Replace with the actual item name
    await page.getByRole('button', { name: 'Add to Cart' }).click();

    const cartCount = await page.getByRole('button', { name: 'Cart' }).getByText(/items/i);
    await expect(cartCount).toHaveText('0'); // Assuming the cart should show 0 items
  });
});
